struct SnapshotReadLeaseSlot {
    generation: u64,
    owner: Arc<dyn std::any::Any + Send + Sync>,
    returned: Arc<std::sync::atomic::AtomicBool>,
}

struct SnapshotReadLeaseRegistryState {
    slots: Box<[std::mem::MaybeUninit<SnapshotReadLeaseSlot>]>,
    occupied: [u64; SNAPSHOT_READ_LEASE_CAPACITY / 64],
    free: [u16; SNAPSHOT_READ_LEASE_CAPACITY],
    free_read: usize,
    free_len: usize,
    next_generation: u64,
    cleanup_cursor: usize,
}

#[derive(Debug)]
enum SnapshotReadLeaseRefusal {
    Busy,
    Poisoned,
    OwnerTypeChanged,
}

impl SnapshotReadLeaseRefusal {
    fn into_value_error(self) -> semio_framework_value::ValueError {
        semio_framework_value::ValueError::new(
            semio_framework_value::ValueRefusalKind::InvariantViolated,
            match self {
                Self::Busy => "snapshot read lease registry is busy",
                Self::Poisoned => "snapshot read lease registry is poisoned",
                Self::OwnerTypeChanged => "snapshot read lease owner type changed inside its exact registry",
            },
        )
    }
}

struct SnapshotReadLeaseStateLock {
    held: std::sync::atomic::AtomicBool,
    poisoned: std::sync::atomic::AtomicBool,
    state: std::cell::UnsafeCell<SnapshotReadLeaseRegistryState>,
}

/// 🔒️ Acquire/Release guards exclusively borrow the Send registry state and never cross threads.
unsafe impl Sync for SnapshotReadLeaseStateLock where SnapshotReadLeaseRegistryState: Send {}

impl SnapshotReadLeaseStateLock {
    fn new(state: SnapshotReadLeaseRegistryState) -> Self { Self { held: std::sync::atomic::AtomicBool::new(false), poisoned: std::sync::atomic::AtomicBool::new(false), state: std::cell::UnsafeCell::new(state) } }
    fn try_lock(&self) -> std::sync::TryLockResult<SnapshotReadLeaseStateGuard<'_>> {
        if self.held.compare_exchange(false, true, std::sync::atomic::Ordering::Acquire, std::sync::atomic::Ordering::Relaxed).is_err() { return Err(std::sync::TryLockError::WouldBlock); }
        let guard = SnapshotReadLeaseStateGuard { lock: self, panicking_on_entry: std::thread::panicking(), not_send: std::marker::PhantomData };
        if self.poisoned.load(std::sync::atomic::Ordering::Relaxed) { Err(std::sync::TryLockError::Poisoned(std::sync::PoisonError::new(guard))) } else { Ok(guard) }
    }
    fn get_mut(&mut self) -> std::sync::LockResult<&mut SnapshotReadLeaseRegistryState> {
        let state = self.state.get_mut();
        if *self.poisoned.get_mut() { Err(std::sync::PoisonError::new(state)) } else { Ok(state) }
    }
}

struct SnapshotReadLeaseStateGuard<'a> { lock: &'a SnapshotReadLeaseStateLock, panicking_on_entry: bool, not_send: std::marker::PhantomData<*mut ()> }

impl std::ops::Deref for SnapshotReadLeaseStateGuard<'_> {
    type Target = SnapshotReadLeaseRegistryState;
    fn deref(&self) -> &Self::Target { unsafe { &*self.lock.state.get() } }
}

impl std::ops::DerefMut for SnapshotReadLeaseStateGuard<'_> {
    fn deref_mut(&mut self) -> &mut Self::Target { unsafe { &mut *self.lock.state.get() } }
}

impl Drop for SnapshotReadLeaseStateGuard<'_> {
    fn drop(&mut self) {
        if !self.panicking_on_entry && std::thread::panicking() { self.lock.poisoned.store(true, std::sync::atomic::Ordering::Relaxed); }
        self.lock.held.store(false, std::sync::atomic::Ordering::Release);
    }
}

struct SnapshotReadLeaseRegistry {
    state: SnapshotReadLeaseStateLock,
    returned: std::sync::atomic::AtomicUsize,
    authority_sequence: std::sync::atomic::AtomicU64,
    authority_generation: std::sync::atomic::AtomicU64,
    authority_revision: [std::sync::atomic::AtomicU64; 4],
}

impl SnapshotReadLeaseRegistry {
    fn new() -> Self {
        let mut free = [0; SNAPSHOT_READ_LEASE_CAPACITY];
        for (index, slot) in free.iter_mut().enumerate() {
            *slot = index as u16;
        }
        Self {
            state: SnapshotReadLeaseStateLock::new(SnapshotReadLeaseRegistryState {
                slots: Box::new([const { std::mem::MaybeUninit::uninit() }; SNAPSHOT_READ_LEASE_CAPACITY]),
                occupied: [0; SNAPSHOT_READ_LEASE_CAPACITY / 64],
                free,
                free_read: 0,
                free_len: SNAPSHOT_READ_LEASE_CAPACITY,
                next_generation: 0,
                cleanup_cursor: 0,
            }),
            returned: std::sync::atomic::AtomicUsize::new(0),
            authority_sequence: std::sync::atomic::AtomicU64::new(0),
            authority_generation: std::sync::atomic::AtomicU64::new(0),
            authority_revision: std::array::from_fn(|_| std::sync::atomic::AtomicU64::new(0)),
        }
    }

    fn publish_authority(&self, generation: u64, revision: [u8; 32]) -> bool {
        let sequence = self.authority_sequence.load(std::sync::atomic::Ordering::Acquire);
        let Some(terminal_sequence) = sequence.checked_add(2) else { return false };
        if sequence & 1 != 0 || self.authority_sequence.compare_exchange(sequence, sequence + 1, std::sync::atomic::Ordering::AcqRel, std::sync::atomic::Ordering::Acquire).is_err() {
            return false;
        }
        self.authority_generation.store(generation, std::sync::atomic::Ordering::Relaxed);
        for (word, bytes) in self.authority_revision.iter().zip(revision.as_chunks::<8>().0.iter()) {
            word.store(u64::from_le_bytes(*bytes), std::sync::atomic::Ordering::Relaxed);
        }
        self.authority_sequence.store(terminal_sequence, std::sync::atomic::Ordering::Release);
        true
    }

    fn authority_matches(&self, generation: u64, revision: [u8; 32]) -> bool {
        let first = self.authority_sequence.load(std::sync::atomic::Ordering::Acquire);
        if first == 0 || first & 1 != 0 || self.authority_generation.load(std::sync::atomic::Ordering::Relaxed) != generation {
            return false;
        }
        for (word, bytes) in self.authority_revision.iter().zip(revision.as_chunks::<8>().0.iter()) {
            if word.load(std::sync::atomic::Ordering::Relaxed) != u64::from_le_bytes(*bytes) {
                return false;
            }
        }
        first == self.authority_sequence.load(std::sync::atomic::Ordering::Acquire)
    }

    fn try_issue<T: Send + Sync + 'static>(self: &Arc<Self>, owner: Arc<T>) -> Result<SnapshotReadLease, Arc<T>> {
        let Ok(mut state) = self.state.try_lock() else {
            return Err(owner);
        };
        if state.free_len == 0 || state.slots.is_empty() {
            return Err(owner);
        }
        let generation = match state.next_generation.checked_add(1) {
            Some(generation) => generation,
            None => return Err(owner),
        };
        let read = state.free_read;
        let index = state.free[read] as usize;
        state.free_read = (state.free_read + 1) % SNAPSHOT_READ_LEASE_CAPACITY;
        state.free_len -= 1;
        state.next_generation = generation;
        let returned = Arc::new(std::sync::atomic::AtomicBool::new(false));
        state.slots[index].write(SnapshotReadLeaseSlot { generation, owner, returned: returned.clone() });
        state.occupied[index / 64] |= 1 << (index % 64);
        Ok(SnapshotReadLease { registry: self.clone(), index: index as u16, generation, returned })
    }

    fn try_take(&self, index: u16, generation: u64) -> Result<Arc<dyn std::any::Any + Send + Sync>, String> {
        let Ok(mut state) = self.state.try_lock() else {
            return Err("snapshot read lease registry is busy".into());
        };
        let index = index as usize;
        let mask = 1 << (index % 64);
        if state.occupied[index / 64] & mask == 0 {
            return Err("snapshot read lease is no longer registered".into());
        }
        let slot = unsafe { state.slots[index].assume_init_ref() };
        if slot.generation != generation {
            return Err("snapshot read lease generation is stale".into());
        }
        let slot = unsafe { state.slots[index].assume_init_read() };
        state.occupied[index / 64] &= !mask;
        let write = (state.free_read + state.free_len) % SNAPSHOT_READ_LEASE_CAPACITY;
        state.free[write] = index as u16;
        state.free_len += 1;
        if slot.returned.load(std::sync::atomic::Ordering::Acquire) {
            self.returned.fetch_sub(1, std::sync::atomic::Ordering::AcqRel);
        }
        Ok(slot.owner)
    }

    fn contains(&self, index: u16, generation: u64) -> bool {
        let Ok(state) = self.state.try_lock() else {
            return true;
        };
        let index = index as usize;
        let mask = 1 << (index % 64);
        state.occupied[index / 64] & mask != 0 && unsafe { state.slots[index].assume_init_ref() }.generation == generation
    }

    fn terminal_is_empty(&self) -> bool {
        self.returned.load(std::sync::atomic::Ordering::Acquire) == 0 && self.state.try_lock().is_ok_and(|state| state.free_len == SNAPSHOT_READ_LEASE_CAPACITY)
    }

    fn has_returned(&self) -> bool {
        self.returned.load(std::sync::atomic::Ordering::Acquire) != 0
    }

    fn next_empty_backing_byte_demand(&self) -> usize {
        self.state.try_lock().map_or(1, |state| state.slots.len().checked_mul(std::mem::size_of::<SnapshotReadLeaseSlot>()).expect("snapshot reader registry backing layout"))
    }

    fn close_empty_backing_step(&self, maximum_items: usize, maximum_bytes: usize) -> Result<SnapshotRetirementStep, ValueError> {
        let mut state = match self.state.try_lock() {
            Ok(state) => state,
            Err(std::sync::TryLockError::WouldBlock) => return Ok(SnapshotRetirementStep::Blocked),
            Err(std::sync::TryLockError::Poisoned(_)) => return Err(SnapshotReadLeaseRefusal::Poisoned.into_value_error()),
        };
        if state.free_len != SNAPSHOT_READ_LEASE_CAPACITY || self.returned.load(std::sync::atomic::Ordering::Acquire) != 0 { return Ok(SnapshotRetirementStep::Blocked); }
        let bytes = state.slots.len().checked_mul(std::mem::size_of::<SnapshotReadLeaseSlot>()).expect("snapshot reader registry backing layout");
        if bytes == 0 { return Ok(SnapshotRetirementStep::Complete); }
        if maximum_items == 0 || maximum_bytes < bytes { return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 }); }
        drop(std::mem::take(&mut state.slots));
        Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: bytes })
    }

    fn occupied_count(&self) -> usize {
        self.state.try_lock().map_or(SNAPSHOT_READ_LEASE_CAPACITY, |state| SNAPSHOT_READ_LEASE_CAPACITY - state.free_len)
    }

    /// 🪶 Releases a lease whose root is still aliased outside this registry, on the returning
    /// thread and in constant time.
    ///
    /// The retirement pump exists for DISPLACED roots: a returned read whose slot holds the last
    /// `Arc` is the only owner left, so its domain tree must be disposed in bounded steps. A read
    /// that is returned while its root is still live — every `ephemeral` hook capture, every tool
    /// job's presence/transient capture — has nothing to dispose, and the pump discovers that two
    /// turns later with an `Arc::into_inner` that simply fails (see
    /// `ReturnedSnapshotReadRetirement::close_step` and the presence local ladder). Charging a
    /// fair maintenance turn per dispatch to rediscover it starves the registry: a mounted app
    /// that dispatches once per frame issues leases faster than one fair step per frame can
    /// reclaim them, and the fixed slot table runs out mid-run.
    fn try_release_aliased(&self, index: u16, generation: u64) -> bool {
        let Ok(mut state) = self.state.try_lock() else { return false };
        let index = index as usize;
        let mask = 1 << (index % 64);
        if state.occupied[index / 64] & mask == 0 {
            return false;
        }
        let slot = unsafe { state.slots[index].assume_init_ref() };
        if slot.generation != generation || slot.returned.load(std::sync::atomic::Ordering::Acquire) || Arc::strong_count(&slot.owner) == 1 {
            return false;
        }
        let slot = unsafe { state.slots[index].assume_init_read() };
        state.occupied[index / 64] &= !mask;
        let write = (state.free_read + state.free_len) % SNAPSHOT_READ_LEASE_CAPACITY;
        state.free[write] = index as u16;
        state.free_len += 1;
        drop(slot);
        true
    }

    fn try_take_one_returned<T: Send + Sync + 'static>(&self) -> Result<Option<Arc<T>>, SnapshotReadLeaseRefusal> {
        let mut state = match self.state.try_lock() {
            Ok(state) => state,
            Err(std::sync::TryLockError::WouldBlock) => return Err(SnapshotReadLeaseRefusal::Busy),
            Err(std::sync::TryLockError::Poisoned(_)) => return Err(SnapshotReadLeaseRefusal::Poisoned),
        };
        let start = state.cleanup_cursor;
        let Some(index) = (0..=state.occupied.len()).find_map(|offset| {
            let word_index = (start / 64 + offset) % state.occupied.len();
            let mut occupied = state.occupied[word_index];
            if offset == 0 {
                occupied &= u64::MAX << (start % 64);
            } else if offset == state.occupied.len() {
                occupied &= (1u64 << (start % 64)) - 1;
            }
            (occupied != 0).then(|| word_index * 64 + occupied.trailing_zeros() as usize)
        }) else {
            return Ok(None);
        };
        state.cleanup_cursor = (index + 1) % SNAPSHOT_READ_LEASE_CAPACITY;
        let mask = 1 << (index % 64);
        if state.occupied[index / 64] & mask == 0 {
            return Ok(None);
        }
        let slot = unsafe { state.slots[index].assume_init_ref() };
        if !slot.returned.load(std::sync::atomic::Ordering::Acquire) {
            return Ok(None);
        }
        if !slot.owner.is::<T>() {
            return Err(SnapshotReadLeaseRefusal::OwnerTypeChanged);
        }
        let slot = unsafe { state.slots[index].assume_init_read() };
        state.occupied[index / 64] &= !mask;
        let write = (state.free_read + state.free_len) % SNAPSHOT_READ_LEASE_CAPACITY;
        state.free[write] = index as u16;
        state.free_len += 1;
        self.returned.fetch_sub(1, std::sync::atomic::Ordering::AcqRel);
        Ok(Some(slot.owner.downcast::<T>().expect("validated snapshot read lease owner type")))
    }
}

impl Drop for SnapshotReadLeaseRegistry {
    fn drop(&mut self) {
        let state = self.state.get_mut().unwrap_or_else(|poisoned| poisoned.into_inner());
        assert!(std::thread::panicking() || state.free_len == SNAPSHOT_READ_LEASE_CAPACITY, "snapshot read lease registry reached Drop before every exact owner was returned and retired: {} of {SNAPSHOT_READ_LEASE_CAPACITY}", state.free_len);
        assert!(std::thread::panicking() || self.returned.load(std::sync::atomic::Ordering::Acquire) == 0, "snapshot read lease registry reached Drop with returned owners outside the bounded retirement pump");
    }
}

struct SnapshotReadLeaseRegistryOwner(Option<Arc<SnapshotReadLeaseRegistry>>);

impl SnapshotReadLeaseRegistryOwner {
    fn new() -> Self { Self(Some(Arc::new(SnapshotReadLeaseRegistry::new()))) }
    fn terminal_is_empty(&self) -> bool { self.0.as_ref().is_none_or(|owner| owner.terminal_is_empty()) }
    fn occupied_count(&self) -> usize { self.0.as_ref().map_or(0, |owner| owner.occupied_count()) }
    fn next_empty_backing_byte_demand(&self) -> usize { self.0.as_ref().map_or(0, |owner| owner.next_empty_backing_byte_demand()) }
    fn close_empty_backing_step(&self, maximum_items: usize, maximum_bytes: usize) -> Result<SnapshotRetirementStep, ValueError> { self.0.as_ref().map_or(Ok(SnapshotRetirementStep::Complete), |owner| owner.close_empty_backing_step(maximum_items, maximum_bytes)) }
    fn frame_byte_demand(&self) -> usize { if self.0.is_none() { 0 } else { std::alloc::Layout::new::<[usize; 2]>().extend(std::alloc::Layout::new::<SnapshotReadLeaseRegistry>()).expect("snapshot registry Arc layout").0.pad_to_align().size() } }
    fn close_frame_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<SnapshotRetirementStep, ValueError> {
        let Some(owner) = self.0.as_ref() else { return Ok(SnapshotRetirementStep::Complete) };
        if !owner.terminal_is_empty() || owner.next_empty_backing_byte_demand() != 0 || Arc::strong_count(owner) != 1 || Arc::weak_count(owner) != 0 { return Ok(SnapshotRetirementStep::Blocked); }
        let extent = self.frame_byte_demand();
        if maximum_items == 0 || maximum_bytes < extent { return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 }); }
        let value = Arc::into_inner(self.0.take().expect("snapshot registry owner remains retained"));
        let released_bytes = if let Some(value) = value { drop(value); extent } else { 0 };
        Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes })
    }
}

impl std::ops::Deref for SnapshotReadLeaseRegistryOwner {
    type Target = Arc<SnapshotReadLeaseRegistry>;
    fn deref(&self) -> &Self::Target { self.0.as_ref().expect("snapshot registry is unavailable after exact owned close") }
}

struct SnapshotReadLease {
    registry: Arc<SnapshotReadLeaseRegistry>,
    index: u16,
    generation: u64,
    returned: Arc<std::sync::atomic::AtomicBool>,
}

#[path="🔗️read/♻️retirement/🦀️.rs"]
mod retained_read_retirement;

impl SnapshotReadLease {
    fn return_now(&mut self) -> bool {
        if self.returned.load(std::sync::atomic::Ordering::Acquire) {
            return false;
        }
        if self.registry.try_release_aliased(self.index, self.generation) {
            self.returned.store(true, std::sync::atomic::Ordering::Release);
            return true;
        }
        self.registry.returned.fetch_add(1, std::sync::atomic::Ordering::AcqRel);
        if self.returned.compare_exchange(false, true, std::sync::atomic::Ordering::AcqRel, std::sync::atomic::Ordering::Acquire).is_err() {
            self.registry.returned.fetch_sub(1, std::sync::atomic::Ordering::AcqRel);
            return false;
        }
        true
    }
}
